contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: artId to create and an amount of wei equal to msg.value supplied to the call
    function run(uint256 artId_, uint256 pay) public payable {
        require(address(this).balance >= pay, "not enough balance to forward");

        // read before-values
        uint256 beforeCounter = c.tokenIdCounter();
        address protoDest = c.protocolFeeDestination();
        uint256 protoBalanceBefore = address(protoDest).balance;
        uint256 cBalanceBefore = address(c).balance;

        // call createArtFromFactory on c as if from this contract with provided value
        bool reverted;
        try c.createArtFromFactory{ value: pay }(artId_) returns (uint256 createdTokenId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterCounter = c.tokenIdCounter();
        uint256 mappedTokenId = c.getTokenIdFromFactoryArtId(artId_);
        uint256 protoBalanceAfter = address(protoDest).balance;
        uint256 cBalanceAfter = address(c).balance;

        // If the call did not revert, then tokenIdCounter must have incremented by exactly 1,
        // the mapping for artId_ must be equal to the previous counter value (i.e. new token id),
        // and the protocol fee destination balance must have increased by exactly the artCreateFee
        // returned by the factory (we observe it via phiFactoryContract.artCreateFee() through c.getArtDataFromFactory).
        // We cannot call internal storage; instead ensure consistency between counter and mapping and fee transfer.

        if (!reverted) {
            // artCreateFee fetched from factory via public phiFactoryContract reference inside c
            // Use getArtDataFromFactory to access artCreateFee for the artId_ (public view)
            IPhiFactory.ArtData memory artData = c.getArtDataFromFactory(artId_);
            uint256 artFee = artData.mintFee; // fallback: if mintFee used differently, still observable

            // The created token id should be the previous counter value
            // and counter should increase by 1
            // Also protocol destination should receive exactly artFee (or if pay < artFee, create may still revert; but here not reverted)
            assert(afterCounter == beforeCounter + 1 && mappedTokenId != 0 && mappedTokenId == beforeCounter && protoBalanceAfter - protoBalanceBefore == artFee);
        } else {
            // If it reverted, then nothing in c should have changed: counter unchanged and mapping still zero
            assert(afterCounter == beforeCounter && mappedTokenId == 0 && protoBalanceAfter == protoBalanceBefore && cBalanceAfter == cBalanceBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to create an art from factory with arbitrary artId_ and wei payment pay
    function run(uint256 artId_, uint256 pay) public payable {
        require(address(this).balance >= pay);

        // observe before
        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeMapped = c.getTokenIdFromFactoryArtId(artId_);

        // perform the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        uint256 returnedTokenId;
        try c.createArtFromFactory{ value: pay }(artId_) returns (uint256 t) {
            reverted = false;
            returnedTokenId = t;
        } catch {
            reverted = true;
            returnedTokenId = 0;
        }

        // observe after
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterMapped = c.getTokenIdFromFactoryArtId(artId_);

        // General invariant:
        // - If call reverted: counter and mapping unchanged.
        // - If call succeeded: counter increased by exactly 1 and mapping for artId_ equals the previous counter (the created token id equals beforeCounter).
        assert(
            reverted
                ? (afterCounter == beforeCounter && afterMapped == beforeMapped)
                : (afterCounter == beforeCounter + 1 && afterMapped == beforeCounter && returnedTokenId == beforeCounter)
        );
    }

    // allow receiving ETH so the test can forward funds
    receive() external payable {}
}

