contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an artId and an ether amount to forward to createArtFromFactory.
    // The test verifies that createArtFromFactory maps artId -> previous tokenIdCounter,
    // increments tokenIdCounter by 1, emits the expected mapping, and that any excess
    // Ether beyond artCreateFee is returned to this contract (observed via address balances).
    function run(uint256 artId, uint256 value) public payable {
        require(address(this).balance >= value, "insufficient balance for test");

        // Read pre-state
        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceThis = address(this).balance;

        // Call createArtFromFactory forwarding value wei. It is external and payable.
        bool reverted = false;
        uint256 createdTokenId = 0;
        try c.createArtFromFactory{value: value}(artId) returns (uint256 tokenId) {
            createdTokenId = tokenId;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterBalanceC = address(c).balance;
        uint256 afterBalanceThis = address(this).balance;
        uint256 mapped = c.getTokenIdFromFactoryArtId(artId);

        // Determine art fee from factory (view call). This is allowed in assert but we read it here.
        uint256 artFee = c.phiFactoryContract().artCreateFee();

        // General rule (only one assert): If the call did NOT revert then
        //  - createdTokenId equals beforeCounter
        //  - mapping for artId equals beforeCounter
        //  - tokenIdCounter incremented by exactly 1
        //  - contract c's balance increased by at most artFee (it receives artFee), and our balance decreased by at least that artFee,
        //    and any excess (value - artFee) was returned to this contract (so our post-balance increased by that excess compared to before after accounting the forwarded value)
        // If the call reverted then no state changes must have occurred (counter unchanged and mapping zero).

        assert(
            (!reverted &&
                createdTokenId == beforeCounter &&
                mapped == beforeCounter &&
                afterCounter == beforeCounter + 1 &&
                // c.balance increased by at most artFee (it may forward to protocol dest); ensure it didn't gain more than artFee
                afterBalanceC - beforeBalanceC <= artFee &&
                // our balance decreased by at least artFee (we paid fee) but if value > artFee the excess was returned so our net decrease is exactly artFee when call succeeded
                beforeBalanceThis - afterBalanceThis == (artFee <= value ? artFee : beforeBalanceThis - afterBalanceThis) 
            ) || (
                reverted &&
                afterCounter == beforeCounter &&
                mapped == 0
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the check described above.
    // We forward `value` wei to the call to allow both cheap and funded paths.
    function run(uint256 artId, uint256 value) public payable {
        require(address(this).balance >= value);

        // observe pre-state via public getters
        uint256 beforeCounter = c.tokenIdCounter();
        uint256 mappedBefore = c.getTokenIdFromFactoryArtId(artId);

        // perform the state-changing call as a top-level statement
        bool reverted;
        uint256 returnedTokenId;
        try c.createArtFromFactory{value: value}(artId) returns (uint256 tokenId) {
            reverted = false;
            returnedTokenId = tokenId;
        } catch {
            reverted = true;
            returnedTokenId = 0;
        }

        // observe post-state via public getters
        uint256 afterCounter = c.tokenIdCounter();
        uint256 mappedAfter = c.getTokenIdFromFactoryArtId(artId);

        // Exactly one assert expressing the general invariant for ALL inputs
        assert(
            // If the call reverted: no change to counter and mapping remains as before
            (reverted && afterCounter == beforeCounter && mappedAfter == mappedBefore)
            ||
            // If it succeeded: returned tokenId equals prior counter, mapping set to prior counter, and counter incremented by 1
            (!reverted && returnedTokenId == beforeCounter && mappedAfter == beforeCounter && afterCounter == beforeCounter + 1)
        );
    }

    receive() external payable {}
}
